#include <stdio.h>



int main(void) {
    double sum = 0, term;
    int k = 0;
    do {
        term = 1.0 / (2 * k + 1);
        sum += k % 2 ? -term : term;
        k++;
    } while (term >= 1e-6);
    printf("%.6f\n", 4 * sum);
    return 0;
}
